    {
        "path": "bellwright-trainer/src/memory_reader.py",
        "content": "import ctypes\nimport ctypes.wintypes\nfrom typing import Optional, List, Tuple\n\nclass MemoryReader:\n    \"\"\"\n    Handles reading and writing process memory for the Bellwright game.\n    Uses Windows API via ctypes for memory operations.\n    \"\"\"\n\n    PROCESS_ALL_ACCESS = 0x1F0FFF\n\n    def __init__(self, process_name: str = \"Bellwright-Win64-Shipping.exe\"):\n        self.process_name = process_name\n        self.process_handle = None\n        self.pid = None\n\n    def open_process(self) -> bool:\n        \"\"\"\n        Opens a handle to the Bellwright process with full access.\n        Returns True if successful, False otherwise.\n        \"\"\"\n        import psutil\n        for proc in psutil.process_iter(['pid', 'name']):\n            if proc.info['name'] == self.process_name:\n                self.pid = proc.info['pid']\n                kernel32 = ctypes.windll.kernel32\n                self.process_handle = kernel32.OpenProcess(\n                    self.PROCESS_ALL_ACCESS,\n                    False,\n                    self.pid\n                )\n                return self.process_handle is not None and self.process_handle > 0\n        return False\n\n    def close_process(self) -> None:\n        \"\"\"Closes the handle to the process.\"\"\"\n        if self.process_handle:\n            ctypes.windll.kernel32.CloseHandle(self.process_handle)\n            self.process_handle = None\n\n    def read_memory(self, address: int, size: int) -> Optional[bytes]:\n        \"\"\"\n        Reads 'size' bytes from the given virtual memory address.\n        Returns bytes object or None on failure.\n        \"\"\"\n        if not self.process_handle:\n            return None\n        buffer = ctypes.create_string_buffer(size)\n        bytes_read = ctypes.c_size_t(0)\n        success = ctypes.windll.kernel32.ReadProcessMemory(\n            self.process_handle,\n            ctypes.c_void_p(address),\n            buffer,\n            size,\n            ctypes.byref(bytes_read)\n        )\n        if success and bytes_read.value == size:\n            return buffer.raw\n        return None\n\n    def write_memory(self, address: int, data: bytes) -> bool:\n        \"\"\"\n        Writes 'data' bytes to the given virtual memory address.\n        Returns True on success.\n        \"\"\"\n        if not self.process_handle:\n            return False\n        bytes_written = ctypes.c_size_t(0)\n        success = ctypes.windll.kernel32.WriteProcessMemory(\n            self.process_handle,\n            ctypes.c_void_p(address),\n            data,\n            len(data),\n            ctypes.byref(bytes_written)\n        )\n        return success and bytes_written.value == len(data)\n\n    def find_pattern(self, pattern: bytes, start_address: int = 0x400000, end_address: int = 0x7FFFFFFF) -> List[int]:\n        \"\"\"\n        Scans memory for a given byte pattern. Returns list of addresses where pattern is found.\n        Only scans readable memory regions (simplified).\n        \"\"\"\n        results = []\n        page_size = 0x1000\n        for addr in range(start_address, end_address, page_size):\n            data = self.read_memory(addr, page_size)\n            if data:\n                offset = 0\n                while True:\n                    pos = data.find(pattern, offset)\n                    if pos == -1:\n                        break\n                    results.append(addr + pos)\n                    offset = pos + 1\n        return results\n"
    },
